      if (completedSteps.includes(idx)) state = 'completed';

      return (
        <Stepper.Step
          description={step.description}
          key={idx}
          state={state}
          title={step.title}
        />
      );
    })}
  </Stepper>
);

const BulletVariant = ({ orientation, variant }) => (
  <Stepper orientation={orientation} variant={variant}>
    <Stepper.Step state='completed' />
